// Category C — no headless signature primitive exists, so the drawing is owned here: pointer events on
// an inline SVG, with the clear action borrowed from Button. Strokes are stored in coordinates
// normalised to 0–1 of the pad and drawn in a 0 0 1 1 viewBox, so the same signature redraws at the same
// proportions on a pad of another size. That is what a paired display needs: a POS and its
// customer-facing screen mirror one stroke on both.
// SVG rather than canvas: the ink is `currentColor` and a token width with `non-scaling-stroke`, so a
// theme or brand switch recolours it and a DPR change stays sharp with no backing-store arithmetic.
//
// One stroke follows one pointer: the primary pointer's main button starts it, and other contacts
// (a palm or a second finger on a counter tablet) are ignored until it ends.
//
// Accessibility. WCAG 2.2 2.1.1 (Keyboard) excepts input that depends on the path of the user's
// movement, which a handwritten signature does. 2.5.1 (Pointer Gestures) and 2.5.7 (Dragging Movements)
// both except a path that is essential, and here the path is the data. An alternative to signing (a
// staff override, a skip) belongs to the consuming flow, not to this component. The pad is named for
// assistive technology, says whether it is empty or signed, and its clear action is a real button that
// stays focusable.
import { useCallback, useEffect, useId, useRef, useState } from "react";
import type { CSSProperties, PointerEvent as ReactPointerEvent, Ref } from "react";
import { Button } from "./Button";
import "./SignaturePad.css";

type SignaturePadSize = "small" | "medium" | "large";

/** One stroke: points as [x, y] fractions of the pad's width and height, in drawing order. */
export type SignatureStroke = [number, number][];

export interface SignaturePadBaseProps {
  /**
   * Size axis: the pad's minimum height. The pad fills the inline size its container gives it.
   *
   * @default "medium"
   */
  size?: SignaturePadSize;
  /** Controlled strokes. Pass the paired device's strokes here to mirror them. */
  value?: SignatureStroke[];
  /** Initial strokes when uncontrolled. */
  defaultValue?: SignatureStroke[];
  /** Called with all strokes after each stroke ends, and with `[]` after clearing. */
  onChange?: (value: SignatureStroke[]) => void;
  /** Visible hint shown centred while the pad is empty, e.g. "Sign here". A hint, not the name. */
  placeholder: string;
  /** Announced as the pad's state once it holds a signature, e.g. "Signed". */
  signedLabel: string;
  /** Visible label of the clear button. */
  clearLabel: string;
  /** When true, drawing and clearing are disabled; the strokes stay visible. */
  isDisabled?: boolean;
  /** The pad's accessible name. Give this or `aria-labelledby`. */
  "aria-label"?: string;
  /** Id of a visible heading that names the pad. Give this or `aria-label`. */
  "aria-labelledby"?: string;
  /** Additional class (optional). sd-signature-pad is always preserved. */
  className?: string;
  /** Inline style for the root element. */
  style?: CSSProperties;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

/** The pad needs an accessible name: either its own `aria-label`, or the id of a visible heading. */
export type SignaturePadProps =
  | (SignaturePadBaseProps & { "aria-label": string; "aria-labelledby"?: never })
  | (SignaturePadBaseProps & { "aria-labelledby": string; "aria-label"?: never });

const clamp = (n: number) => Math.min(1, Math.max(0, n));
const points = (s: SignatureStroke) => s.map(([x, y]) => `${x},${y}`).join(" ");

export function SignaturePad({
  size = "medium",
  value,
  defaultValue = [],
  onChange,
  placeholder,
  signedLabel,
  clearLabel,
  isDisabled = false,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  className,
  style,
  ref,
}: SignaturePadProps) {
  const [inner, setInner] = useState<SignatureStroke[]>(defaultValue);
  const strokes = value ?? inner;
  // The stroke being drawn lives in a ref, so every move appends to the live stroke even when several
  // arrive before a re-render; the state copy only triggers the redraw.
  const live = useRef<SignatureStroke | null>(null);
  const [current, setCurrent] = useState<SignatureStroke | null>(null);
  const pointer = useRef<number | null>(null);
  const statusId = useId();

  const commit = useCallback(
    (next: SignatureStroke[]) => {
      if (value === undefined) setInner(next);
      onChange?.(next);
    },
    [value, onChange],
  );

  const at = (e: ReactPointerEvent<SVGSVGElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    return [clamp((e.clientX - r.left) / r.width), clamp((e.clientY - r.top) / r.height)];
  };

  // Ends the stroke in progress and keeps what was drawn, whether the pointer lifted, was cancelled or
  // lost its capture.
  const end = () => {
    if (pointer.current === null) return;
    pointer.current = null;
    const stroke = live.current;
    live.current = null;
    if (stroke && stroke.length > 0 && !isDisabled) commit([...strokes, stroke]);
    setCurrent(null);
  };

  // Turning disabled mid-stroke drops the stroke at once, rather than letting it draw under the dimmed
  // surface until the pointer lifts.
  useEffect(() => {
    if (!isDisabled || pointer.current === null) return;
    pointer.current = null;
    live.current = null;
    setCurrent(null);
  }, [isDisabled]);

  const empty = strokes.length === 0 && current === null;

  return (
    <div
      ref={ref}
      data-size={size}
      className={className ? `sd-signature-pad ${className}` : "sd-signature-pad"}
      style={style}
    >
      <svg
        className="sd-signature-pad__surface"
        data-disabled={isDisabled || undefined}
        viewBox="0 0 1 1"
        preserveAspectRatio="none"
        role="img"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        aria-describedby={statusId}
        onPointerDown={(e) => {
          if (isDisabled || pointer.current !== null || !e.isPrimary || e.button !== 0) return;
          pointer.current = e.pointerId;
          e.currentTarget.setPointerCapture(e.pointerId);
          live.current = [at(e)];
          setCurrent(live.current);
        }}
        onPointerMove={(e) => {
          if (e.pointerId !== pointer.current || !live.current) return;
          // ponytail: copies the stroke per move (O(n²) per stroke), fine at signature length.
          live.current = [...live.current, at(e)];
          setCurrent(live.current);
        }}
        onPointerUp={(e) => e.pointerId === pointer.current && end()}
        onPointerCancel={(e) => e.pointerId === pointer.current && end()}
        onLostPointerCapture={(e) => e.pointerId === pointer.current && end()}
      >
        {/* A tap is a one-point stroke: drawn as a zero-length line, its round cap makes the dot, which
            a circle could not in a viewBox stretched by preserveAspectRatio="none". */}
        {[...strokes, ...(current ? [current] : [])].map((s, i) => (
          <polyline key={i} className="sd-signature-pad__stroke" vectorEffect="non-scaling-stroke" points={points(s.length === 1 ? [s[0], s[0]] : s)} />
        ))}
      </svg>
      <span id={statusId} className="sd-visually-hidden">
        {empty ? placeholder : signedLabel}
      </span>
      {empty && (
        <span
          className={`sd-signature-pad__placeholder sd-type-body-${size}`}
          data-disabled={isDisabled || undefined}
          aria-hidden="true"
        >
          {placeholder}
        </span>
      )}
      <Button
        className="sd-signature-pad__clear"
        size={size}
        variant="secondary"
        isDisabled={isDisabled}
        onPress={() => strokes.length > 0 && commit([])}
      >
        {clearLabel}
      </Button>
    </div>
  );
}

/* A drawing surface that fills the inline size its container gives it, at least the minimum height
   of its size. The strokes are SVG: `currentColor` ink and a token width that `non-scaling-stroke`
   keeps constant whatever the pad's size or the display's density. */
.sd-signature-pad {
  position: relative;
  inline-size: 100%;
  overflow: hidden;
  border: var(--sd-signature-pad-border-width) solid var(--sd-signature-pad-border);
  border-radius: var(--sd-signature-pad-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-signature-pad-background);
}

.sd-signature-pad[data-size="small"] {
  min-block-size: var(--sd-signature-pad-min-height-small);
}
.sd-signature-pad[data-size="medium"] {
  min-block-size: var(--sd-signature-pad-min-height-medium);
}
.sd-signature-pad[data-size="large"] {
  min-block-size: var(--sd-signature-pad-min-height-large);
}

.sd-signature-pad__surface {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  color: var(--sd-signature-pad-stroke-color);
  /* the pad owns every pointer move while signing: no scroll, pan or pinch */
  touch-action: none;
  cursor: crosshair;
}

/* Disabled dims the surface and the hint, not the root: the clear Button dims itself, and dimming the
   root too would multiply the two. */
.sd-signature-pad__surface[data-disabled] {
  touch-action: auto;
  cursor: not-allowed;
  opacity: var(--sd-state-disabled);
}

.sd-signature-pad__placeholder[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-signature-pad__stroke {
  fill: none;
  stroke: currentColor;
  stroke-width: var(--sd-signature-pad-stroke-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.sd-signature-pad__placeholder {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  padding-inline: var(--sd-signature-pad-inset);
  text-align: center;
  color: var(--sd-signature-pad-placeholder-foreground);
  pointer-events: none;
}

.sd-signature-pad__clear {
  position: absolute;
  inset-inline-end: var(--sd-signature-pad-inset);
  inset-block-end: var(--sd-signature-pad-inset);
}
